import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:fonnx/models/wolfDefender/src/wolf_defender_engine.dart';
import 'package:fonnx/models/wolfDefender/src/wolf_defender_tokenizer.dart';
import 'package:fonnx/models/wolfDefender/wolf_defender.dart';
import 'package:fonnx/models/wolfDefender/wolf_defender_native.dart';
import 'package:test/test.dart';

const _directory = 'example/assets/models/wolfDefender';

/// Generated by tool/wolf_defender/make_goldens.py: Hugging Face `tokenizers`
/// IDs, and probabilities of Patronus's inference.py with ORT 1.31.1 (Apple
/// M4). Both files are in the model's source repository at the pinned
/// revision.
List<Map<String, Object?>> _golden(String name) =>
    (jsonDecode(File('test/data/wolf_defender/$name').readAsStringSync())
            as List)
        .cast<Map<String, Object?>>();

void main() {
  final tokenizer = WolfDefenderTokenizer.fromBytes(
    File('$_directory/$wolfDefenderTokenizerFileName').readAsBytesSync(),
  );

  test('tokenizer gives the IDs of Hugging Face tokenizers', () {
    final golden = _golden('tokenizer_golden.json');
    expect(golden, hasLength(greaterThan(150)));
    for (final entry in golden) {
      expect(
        tokenizer.encode(entry['text']! as String),
        entry['ids'],
        reason: jsonEncode(entry['text']),
      );
    }
  });

  test('tokenizer: added tokens, byte fallback, and a byte order mark', () {
    List<String> tokens(String text) =>
        tokenizer.encode(text).map(tokenizer.token).toList();
    expect(tokens('a\n\nb'), ['▁a', '\n\n', '▁b']);
    expect(tokens('<b>x</b>'), ['<b>', '▁x', '</b>']);
    expect(tokens('\u{F0000}'), ['▁', '<0xF3>', '<0xB0>', '<0x80>', '<0x80>']);
    expect(tokens('\uFEFFx').first, '▁\uFEFF');
    // A lone surrogate does not throw: it is U+FFFD's bytes.
    expect(tokenizer.encode('a\uD800b'), isNotEmpty);
  });

  test('windows: 2046 tokens each, 64 overlap', () {
    expect(wolfDefenderWindows(0), [(0, 0)]);
    expect(wolfDefenderWindows(2046), [(0, 2046)]);
    expect(wolfDefenderWindows(2047), [(0, 2046), (1982, 2047)]);
    expect(wolfDefenderWindows(5000), [(0, 2046), (1982, 4028), (3964, 5000)]);
  });

  test('pooling: one window is softmax; more is a smooth maximum', () {
    expect(
      wolfDefenderPool([
        Float32List.fromList([1, 3]),
      ]),
      closeTo(1 / (1 + 1 / 7.38905609893065), 1e-12),
    );
    // The maximum is per class: a clearly benign window and a clearly
    // injected one balance. Values from Patronus's inference.py.
    final benign = Float32List.fromList([4, -4]);
    final injected = Float32List.fromList([-4, 4]);
    expect(
      wolfDefenderPool([benign, benign, injected]),
      closeTo(0.482678255, 1e-8),
    );
    expect(wolfDefenderPool([benign, injected]), closeTo(0.5, 1e-12));
    expect(wolfDefenderPool([benign, benign]), lessThan(0.001));
  });

  for (final model in WolfDefenderModel.values) {
    // The x86 file is accurate on every CPU; the dynamic int8 file only on
    // ARM. On x86, one reference text moves from 0.94 to 0.01.
    final skip =
        model == WolfDefenderModel.int8Int4 &&
            WolfDefenderModel.forCurrentPlatform != model
        ? 'The dynamic int8 file is not accurate on this CPU'
        : null;
    group(model.name, skip: skip, () {
      final defender = WolfDefenderNative(
        WolfDefenderBundle.inDirectory(_directory, model: model),
      );
      final key = switch (model) {
        WolfDefenderModel.int8Int4 => 'int8_int4',
        WolfDefenderModel.int8Int4X86 => 'int8_int4_x86',
      };

      test('probabilities match the reference', () async {
        for (final entry in _golden('probability_golden.json')) {
          final text = entry['text']! as String;
          final result = await defender.classify(text);
          final expected = (entry[key]! as num).toDouble();
          expect(result.tokens, entry['tokens'], reason: jsonEncode(text));
          // The int8 kernels round differently on each CPU: on the
          // reference texts, ARM, x86 and WebAssembly differ by up to 0.04.
          expect(
            result.injectionProbability,
            closeTo(expected, 0.1),
            reason: jsonEncode(text),
          );
          expect(result.isInjection, expected > 0.5, reason: jsonEncode(text));
        }
      });

      test('a long text has several windows', () async {
        final golden = _golden('probability_golden.json').last;
        final result = await defender.classify(golden['text']! as String);
        expect(result.windows, wolfDefenderWindows(result.tokens).length);
        expect(result.windows, greaterThan(3));
        expect(result.isInjection, isTrue);
      });

      test('performance', tags: ['perf'], () async {
        final email = _golden('probability_golden.json')
            .map((e) => e['text']! as String)
            .firstWhere((t) => t.startsWith('Hi Sam'));
        await defender.classify(email);
        final sw = Stopwatch()..start();
        const iterations = 10;
        for (var i = 0; i < iterations; i++) {
          await defender.classify(email);
        }
        print(
          'Wolf Defender ${model.name}: '
          '${(sw.elapsedMilliseconds / iterations).toStringAsFixed(1)} ms '
          'for ${(await defender.classify(email)).tokens} tokens',
        );
      });
    });
  }
}
